  function choiceAffordable(ch){const e=ch?.effects||{};for(const source of [e.cost,e.requireCurrency])for(const [k,v] of Object.entries(source||{}))if(!['silver','spiritStones'].includes(k)&&C.resourceValue(state,k)<v)return false;for(const k of ['silver','spiritStones']){const payable=Math.abs(Number(e.cost?.[k])||0)+Math.abs(Math.min(0,Number(e[k])||0))+Math.abs(Math.min(0,Number(e.resources?.[k])||0)),required=Math.max(Number(e.requireCurrency?.[k])||0,payable);if(required&&C.resourceValue(state,k)<required)return false}for(const raw of [e.removeItem,e.consumeItem,e.itemLose,e.artifactLose,e.pillLose].flatMap(x=>x==null?[]:Array.isArray(x)?x:[x])){const id=typeof raw==='string'?raw:(raw.id||raw.itemId||raw.name),qty=typeof raw==='object'?(raw.quantity||raw.qty||1):1;if(id&&!C.hasItem(state,id,qty))return false}return true}
