  function mortalChainForYear(year){const chain=C.pickMortalChain(state,[...D.MORTAL_CHAINS,...V21_EVENTS],year,()=>rng.next());syncRng();return chain||D.MORTAL_CHAINS.find(c=>c.phase==='mortal'&&c.yearRange?.[0]===year)||D.MORTAL_CHAINS[0]}
  function nextMortalYear(){state.year++;state.age++;state.currentTurn={selected:[],completed:[],logs:[]};ui.turnSummary=null;if(state.year===9){state.phase='assembly';ui.screen='assembly-transition';audio.play('assembly');render()}else{state.phase='mortal';openChain(mortalChainForYear(state.year+1).eventId)}}
  function enterMortal(){state.phase='mortal';state.year=0;state.age=10;state.currentTurn={selected:[],completed:[],logs:[]};log('此生落笔',`${state.name}生于大周青石村，命数 ${state.seed}。`);audio.play('mortal');openChain(mortalChainForYear(1).eventId)}
  function decideInnate(){state.innateTags=[];for(const t of D.INNATE_TAGS){if(state.attributes[t.attr]>=t.at)addUnique(state.innateTags,t.name)}if(!state.innateTags.length)addUnique(state.innateTags,'白身问道');if(state.attributes.tipo===0)addUnique(state.innateTags,'肉身孱弱');if(state.attributes.daoxin===0)addUnique(state.innateTags,'心湖无锚');if(state.attributes.meili===0)addUnique(state.innateTags,'孤命');C.activateInnateTraits(state,[]);}
  function chainNpcId(chain){return chain?.npcId||chain?.relatedNpcId||D.NPCS.find(n=>String(chain?.eventId||chain?.chainId||'').includes(n.id))?.id||null}
  function applySectEntry(id){const sect=V.SECTS?.[id];state.sect=id;state.sectState={...state.sectState,sectId:id,rankId:id==='sanxiu'?'wanderer':'outer',rank:id==='sanxiu'?'无名散修':'外门弟子',contribution:0,reputation:0,unlockedFacilities:[],activeMissions:[]};if(sect?.initialMods)C.applyTransaction(state,{attributes:{...sect.initialMods}},{source:'入门根基',skipRequirements:true});for(const effect of sect?.passive?.effects||[]){if(effect.trigger==='derived'&&effect.operation==='add'&&['maxHp','lifespan'].includes(effect.target))C.changeResource(state,effect.target,effect.value)}C.updateSectRank(state,[]);C.refreshSectMissions(state);if(id==='qingxuan')C.changeRelation(state,'luchenzhou',5,'收入门下',[])}
  function chooseSect(id){if(!(state.flags.invites||[]).includes(id))return;applySectEntry(id);ui.selectedSect=id;ui.screen='path-choice';render()}
  function acceptHiddenRescue(){applySectEntry('sanxiu');state.flags.hiddenRescue=true;state.flags.invites=['sanxiu'];log('因果回响',`第八年，你曾在桥下帮助莫问尘。今日百宗不收，他却说：“他们不要你，我要。”`);ui.screen='path-choice';render()}
  function rejectToEnding(){showEnding('仙途断绝','九座高台始终无人开口。你站在人群外，看着飞舟一艘艘消失在云海。那一年，你二十岁。此后六十余载，再未见过山巅那一日的仙人。','mortal')}
  function choosePath(id){const p=byId(D.PATHS,id);if(!p)return;state.path=id;const notes=[];C.learnSkill(state,p.skill,notes);state.affinities[p.affinity]=(state.affinities[p.affinity]||0)+2;const starter=({sword:'green_edge_wood_sword',blade:'thick_back_chopping_blade',staff:'ironwood_staff',spear:'white_wax_spear',alchemy:'healing_pill',talisman:'heart_guard_talisman'})[id];if(starter)C.addItem(state,starter,id==='alchemy'?2:1,notes);state.spiritStones=12;state.lifespan+=28;state.realm=1;state.cultivation=10;state.unspentSkillPoints=2;state.phase='cultivation';state.year=10;state.age=20;state.titles.push(`${byId(D.SECTS,state.sect)?.name||'无门'}弟子`);C.evaluateTitles(state,notes);log('拜入仙门',`${state.name}拜入${byId(D.SECTS,state.sect)?.name||'无门传承'}，主修${p.name}，得《${p.skill}》。`,{notes});prepareDecade();}
  function availableChains(){
    const due=state.worldEvents.filter(w=>w.status==='countdown'&&w.dueYear<=state.year);const dueF=state.futureTriggers.filter(f=>f.dueYear<=state.year&&!f.done),actionIds=new Set(state.currentTurn.actions.map(a=>a.id));if(actionIds.has('founding_work'))actionIds.add('sect_mission');let pool=[...D.CULTIVATION_CHAINS.filter(c=>c.phase==='cultivation'),...V21_EVENTS.filter(c=>['cultivation','world'].includes(c.phase)||!c.phase),...legacyChains()];pool=[...new Map(pool.map(c=>[c.chainId||c.eventId,c])).values()].filter(c=>C.eventActionEligible(state,c,actionIds));
    const scheduledIds=new Set([...state.worldEvents.map(w=>w.chain),...state.futureTriggers.map(f=>f.eventId)]);
    pool=pool.filter(c=>!scheduledIds.has(c.chainId)&&!scheduledIds.has(c.eventId)).filter(c=>!(state.deferredEventNodes||[]).some(d=>d.eventId===c.eventId)).filter(c=>state.age>=(c.yearRange?.[0]??20)&&state.age<=(c.yearRange?.[1]??999)).filter(c=>requirementOK(c.triggerRequirements||c.trigger||c.requirements)).filter(c=>!c.unique||!state.completedChains[c.chainId]).filter(c=>!state.recentChains.some(r=>r.id===c.chainId&&state.year-r.year<(c.cooldown||0)*10));
    const picks=[];for(const w of due){const c=getChain(w.chain);if(c&&!picks.some(x=>x.eventId===c.eventId))picks.push(c);w.status='active'}for(const f of dueF){const scheduledWorld=state.worldEvents.find(w=>w.id===f.eventId);const c=getChain(f.eventId)||getChain(scheduledWorld?.chain);if(c&&!picks.some(x=>x.eventId===c.eventId))picks.push(c);if(scheduledWorld)scheduledWorld.status='active';f.done=true}
    const target=Math.max(picks.length,rng.int(2,3));while(picks.length<target&&pool.length){let pick=rng.weighted(pool,c=>C.eventSelectionWeight(state,c));if(!pick)break;picks.push(pick);pool=pool.filter(c=>c.eventId!==pick.eventId&&c.chainId!==pick.chainId)}
    if(!picks.length)picks.push(getChain('fallback'));syncRng();return picks;
  }
  function prepareDecade(){const skipped=Boolean(state.flags.skipNextDecade);delete state.flags.skipNextDecade;state.currentTurn={actionPoints:skipped?0:6,maxActionPoints:6,stage:'planning',actions:[],selected:[],completed:[],logs:skipped?['玄龟息续命后的长眠耗去了整个十年。']:[]};ui.screen='decade';ui.turnSummary=null;ui.actionResult=null;audio.play('sect');if(skipped)beginEventStage();else render()}
