  function canBreak(){const turnReady=state.currentTurn?.stage!=='events'||state.currentTurn.completed.length>=state.currentTurn.selected.length;return state.phase==='cultivation'&&turnReady&&state.realm<D.REALMS.length-1&&state.cultivation>=D.REALMS[state.realm].need}
